def build_matched_workspace_routine_context(task: dict[str, Any]) -> str:
    """Expose established LabCanvas entrypoints before generic tool guidance."""

    request = sanitize_worker_agent_text(task_focus_text(task), max_len=5000)
    if not request:
        return ""
    source_root = ROOT / "src"
    if str(source_root) not in sys.path:
        sys.path.insert(0, str(source_root))
    try:
        from agenticapp.workspace_agent import selected_routine_contracts
    except ImportError:
        return ""
    contracts = selected_routine_contracts(request, ROOT)[:4]
    if not contracts:
        return ""
    task_preflight = task.get("preflight") if isinstance(task.get("preflight"), dict) else {}
    routine_snapshot = (
        task_preflight.get("established_routine_snapshot")
        if isinstance(task_preflight.get("established_routine_snapshot"), dict)
        else {}
    )
    lines = [
        "Matched established LabCanvas routines (authoritative for this request):",
    ]
    if routine_snapshot.get("ok") and isinstance(routine_snapshot.get("snapshot"), dict):
        lines.extend(
            [
                "- LabCanvas already ran the matched read-only command on the host and included its authoritative snapshot in `preflight.established_routine_snapshot`.",
                "- Do not rerun that command inside Docker or probe alternate wrappers, source code, processes, or private ledgers. Summarize the snapshot and stop when it answers the request.",
            ]
        )
    else:
        lines.extend(
            [
                "- Run the first relevant declared command directly before probing help, alternate wrappers, source code, processes, or private ledgers.",
                "- If that command answers the request, stop discovery and return the concise verified result.",
            ]
        )
    for contract in contracts:
        routine_id = str(contract.get("id") or "")
        title = str(contract.get("title") or routine_id)
        readiness = "ready" if contract.get("ready") else "not-ready"
        lines.append(f"- `{routine_id}` ({readiness}): {title}")
        for command in list(contract.get("commands") or [])[:5]:
            lines.append(f"  - `{command}`")
        guidance = collapse_context_text(contract.get("guidance"), max_len=900)
        if guidance:
            lines.append(f"  - Guidance: {guidance}")
    return "\n".join(lines)


def build_existing_video_publish_tool_context(task: dict[str, Any]) -> str:
    if task_routine_id(task) != "video_publish_existing":
        return ""
    platforms = detect_publish_platforms(task, current_only=True)
    cli_value = ",".join(platforms)
    return f"""
Exact existing-video publication contract:
- The current-message platform allowlist is exactly: `{cli_value}`.
- Invoke LazyEdit with one literal `--platforms {cli_value}` argument. Do not use repeated `--platform` flags, because the CLI's default platform list would remain active.
- `--use-current-settings` may inherit subtitle, logo, crop, and layout settings only. It must not broaden the platform allowlist.
- Immediately inspect the created LazyEdit job and require its `platforms` set to equal `{cli_value}`. If it differs, report the mismatch and do not submit or reissue another public job.
"""


def build_media_resolution_tool_context(task: dict[str, Any]) -> str:
    preflight = task.get("preflight") if isinstance(task.get("preflight"), dict) else {}
    media = preflight.get("media_resolution") if isinstance(preflight.get("media_resolution"), dict) else {}
    if not media:
        return ""
    copied = media.get("copied") if isinstance(media.get("copied"), list) else []
    if not copied:
        return (
            "- Media resolution preflight ran but did not find a source-scoped local file. "
            f"Manifest: `{media.get('manifest_md') or media.get('manifest_json') or ''}`. "
            "Do not claim the image/file is unavailable until you have checked this manifest and the source rows.\n"
        )
    lines = [
        "- Media resolution preflight found source-scoped local files. Use these paths as the first-choice inputs for this task:",
    ]
    for item in copied[:8]:
        if not isinstance(item, dict):
            continue
        lines.append(
            f"  - `{item.get('task_copy_path')}` "
            f"suffix={item.get('suffix')} bytes={item.get('size_bytes')} "
            f"score={item.get('score')} reasons={','.join(str(reason) for reason in item.get('match_reasons') or [])}"
        )
        metadata = item.get("image_metadata") if isinstance(item.get("image_metadata"), dict) else {}
        if metadata.get("status") == "ok":
            lines.append(
                f"    image={metadata.get('width')}x{metadata.get('height')} "
                f"format={metadata.get('format') or ''}"
            )
        vision = item.get("vision") if isinstance(item.get("vision"), dict) else {}
        if vision:
            if vision.get("text_path"):
                lines.append(f"    Codex image read: `{vision.get('text_path')}` status={vision.get('status')} model={vision.get('model')}")
            if vision.get("text_preview"):
                lines.append(f"    Codex image preview: {collapse_context_text(vision.get('text_preview'), max_len=500)}")
        ocr = item.get("ocr") if isinstance(item.get("ocr"), dict) else {}
        if ocr:
            if ocr.get("text_path"):
                lines.append(f"    OCR text: `{ocr.get('text_path')}` status={ocr.get('status')}")
            if ocr.get("text_preview"):
                lines.append(f"    OCR preview: {collapse_context_text(ocr.get('text_preview'), max_len=360)}")
    if media.get("manifest_md") or media.get("manifest_json"):
        lines.append(f"  - Manifest: `{media.get('manifest_md') or media.get('manifest_json')}`")
    lines.append("  - For image-reading tasks, use the Codex image read text first, then OCR text, then inspect the image file itself if more visual context is needed.")
    lines.append("  - Do not say the image/file is missing if one of these files exists and matches the requested source.")
    return "\n".join(lines) + "\n"


def safe_slug(value: str) -> str:
    slug = re.sub(r"[^0-9A-Za-z_.-]+", "-", value.strip()).strip("-").lower()
    return slug[:96] or "task"


