def task_routine_id(task: dict[str, Any]) -> str:
    routine = task.get("routine")
    if isinstance(routine, dict):
        return str(routine.get("id") or "")
    return ""


def task_routine_default_effort(task: dict[str, Any]) -> str:
    routine = task.get("routine")
    if isinstance(routine, dict):
        return normalize_effort(str(routine.get("default_effort") or ""), fallback="")
    return ""


def worker_policy_text(task: dict[str, Any]) -> str:
    """Return only user/task-relevant text for effort selection.

    Queue entries can contain long reusable playbooks and source-isolation
    instructions. Those are important for execution but should not make a small
    edit or writing task look like an xhigh autonomous implementation task.
    """
    request = str(task.get("request") or "")
    focused = extract_current_request_for_policy(request)
    pieces = [focused or request]
    source = task.get("source")
    if isinstance(source, dict):
        pieces.append(str(source.get("chat") or ""))
    context = task.get("context")
    if isinstance(context, list):
        for item in context[-3:]:
            if isinstance(item, dict):
                pieces.append(str(item.get("content") or ""))
    return "\n".join(piece for piece in pieces if piece).strip()


def extract_current_request_for_policy(request: str) -> str:
    text = str(request or "")
    patterns = [
        ("Current coalesced request:", "\n\nRecent history:"),
        ("Current request:", "\n\nRecent history:"),
        ("Current message:", "\n\nRecent history:"),
    ]
    for start_marker, end_marker in patterns:
        start = text.find(start_marker)
        if start < 0:
            continue
        start += len(start_marker)
        end = text.find(end_marker, start)
        if end < 0:
            end = len(text)
        return text[start:end].strip()
    return ""


def load_worker_model_policy(effort: str = "medium") -> dict[str, str]:
    """Read the shared model policy for the standalone WeChat worker."""
    try:
        data = json.loads(MODEL_POLICY_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        data = {}
    normalized = normalize_effort(effort, fallback="medium")
    section = {"low": "chat", "medium": "task"}.get(normalized, normalized)
    primary = data.get(section) if isinstance(data, dict) and isinstance(data.get(section), dict) else {}
    fallback_root = data.get("fallback") if isinstance(data, dict) and isinstance(data.get("fallback"), dict) else {}
    fallback = fallback_root.get(section) if isinstance(fallback_root.get(section), dict) else {}
    return {
        "model": str(primary.get("model") or DEFAULT_WORKER_MODEL),
        "reasoning_effort": str(primary.get("reasoning_effort") or section),
        "fallback_model": str(fallback.get("model") or "gpt-5.6-sol"),
        "fallback_reasoning_effort": str(fallback.get("reasoning_effort") or section),
    }


def worker_model(effort: str = "medium") -> str:
    raw = os.environ.get("WECHAT_WORKER_CODEX_MODEL", "").strip()
    model = raw or load_worker_model_policy(effort).get("model", DEFAULT_WORKER_MODEL)
    if "spark" in model.lower() and os.environ.get("WECHAT_ALLOW_SPARK_WORKER", "0") != "1":
        return DEFAULT_WORKER_MODEL
    return model


def worker_min_effort() -> str:
    configured = normalize_effort(
        os.environ.get("WECHAT_WORKER_MIN_EFFORT", "low"),
        fallback="low",
    )
    return clamp_effort(configured, min_effort="low", max_effort="xhigh")


def worker_max_effort() -> str:
    configured = normalize_effort(
        os.environ.get("WECHAT_WORKER_MAX_EFFORT", "xhigh"),
        fallback="xhigh",
    )
    return clamp_effort(configured, min_effort="low", max_effort="xhigh")


def normalize_effort(value: str | None, *, fallback: str) -> str:
    effort = str(value or "").strip().lower()
    return effort if effort in EFFORT_ORDER else fallback


def clamp_effort(effort: str, *, min_effort: str, max_effort: str) -> str:
    effort = normalize_effort(effort, fallback="medium")
    min_index = EFFORT_ORDER.index(normalize_effort(min_effort, fallback="medium"))
    max_index = EFFORT_ORDER.index(normalize_effort(max_effort, fallback="xhigh"))
    if min_index > max_index:
        min_index, max_index = max_index, min_index
    index = EFFORT_ORDER.index(effort)
    index = max(min_index, min(index, max_index))
    return EFFORT_ORDER[index]


def timeout_for_effort(effort: str) -> int:
    normalized = normalize_effort(effort, fallback="medium")
    env_name = f"WECHAT_WORKER_TIMEOUT_{normalized.upper()}_SECONDS"
    raw = os.environ.get(env_name)
    if raw:
        try:
            return max(30, int(raw))
        except ValueError:
            pass
    return EFFORT_TIMEOUT_SECONDS[normalized]


def worker_sandbox() -> str:
    raw = os.environ.get("WECHAT_WORKER_CODEX_SANDBOX", "danger-full-access").strip()
    aliases = {
        "full": "danger-full-access",
        "full-access": "danger-full-access",
        "danger": "danger-full-access",
        "workspace": "workspace-write",
    }
    return aliases.get(raw, raw or "danger-full-access")


def escalated_policy(policy: dict[str, Any], result: str, *, task: dict[str, Any] | None = None) -> dict[str, Any] | None:
    if task is not None and is_generate_video_task(task) and generated_video_result_has_progress(result):
        return None
    if not worker_result_needs_escalation(result):
        return None
    effort = str(policy.get("reasoning_effort") or "medium")
    try:
        index = EFFORT_ORDER.index(effort)
    except ValueError:
        index = 1
    if index >= len(EFFORT_ORDER) - 1:
        return None
    next_effort = EFFORT_ORDER[index + 1]
    next_effort = clamp_effort(next_effort, min_effort=worker_min_effort(), max_effort=worker_max_effort())
    if next_effort == effort:
        return None
    return {
        **policy,
        "model": worker_model(next_effort),
        "reasoning_effort": next_effort,
        "timeout_seconds": timeout_for_effort(next_effort),
        "escalated_from": effort,
    }


def generated_video_result_has_progress(result: str) -> bool:
    text = str(result or "").lower()
    markers = [
        ".mp4",
        ".mov",
        ".webm",
        "submitted",
        "queued",
        "running",
        "generating",
        "blocked",
        "waiting",
        "in progress",
        "已提交",
        "排队",
        "生成中",
        "等待",
        "阻塞",
        "卡住",
    ]
    return any(marker in text for marker in markers)


def worker_result_needs_escalation(result: str) -> bool:
    raw = str(result or "").strip()
    if not raw:
        return True
    payload = extract_worker_json_payload(raw)
    if isinstance(payload, dict):
        message = str(payload.get("message") or "").strip()
        confirmation = str(payload.get("confirmation") or payload.get("confirm") or "").strip()
        files = file_entries_from_json(payload)
        if is_no_reply_control(message) or is_no_reply_control(confirmation):
            return False
        if confirmation or files:
            return False
        if not message:
            return True
        text = message.lower()
    else:
        text = raw.lower()
    if not text:
        return True
    if worker_result_is_terminal_blocker(text):
        return False
    if worker_result_is_infrastructure_failure(text):
        return False
    if worker_result_is_explicit_failure(text):
        return True
    return len(text) < 80


def worker_result_is_explicit_failure(text: str) -> bool:
    normalized = str(text or "").strip().lower()
    prefixes = (
        "worker failed",
        "codex failed",
        "agent backend failed",
        "failed before completion",
        "timed out before",
        "timeout before",
        "cannot complete",
        "can't complete",
        "unable to complete",
        "i cannot complete",
        "i can't complete",
        "无法完成",
        "不能完成",
        "没有完成",
        "任务失败",
        "处理失败",
    )
    return normalized.startswith(prefixes)


def worker_result_is_repairable_tool_failure(result: str) -> bool:
    """Recognize a failed agent tool invocation that merits one repair turn.

    This is intentionally narrower than general worker failure handling. It
    covers malformed shell/tool construction while excluding human approval,
    access, and safety boundaries.
    """
    text = str(result or "").strip().lower()
    if not worker_result_is_explicit_failure(text):
        return False
    if worker_result_is_terminal_blocker(text) or worker_result_is_infrastructure_failure(text):
        return False
    denied_markers = (
        "approval required",
        "requires approval",
        "permission denied",
        "sandbox denied",
        "not permitted by policy",
        "blocked by policy",
        "unsafe command",
    )
    if any(marker in text for marker in denied_markers):
        return False
    repairable_markers = (
        "exec_command failed",
        "codex_core::tools::router",
        "createprocess { message: \"rejected",
        "createprocess rejected",
        "unterminated quoted string",
        "unexpected eof while looking for matching",
        "syntax error near unexpected token",
    )
    return any(marker in text for marker in repairable_markers)


def worker_result_is_recoverable_aginti_permission_pause(result: str) -> bool:
    """Retry one AgInTi policy pause without broadening the worker's authority."""

    text = " ".join(str(result or "").strip().lower().split())
    if not text.startswith("worker failed via aginti:"):
        return False
    return "permission_required" in text or "permission required" in text


def worker_result_quality(result: str) -> int:
    """Score a worker turn without mistaking source limitations for failure.

    A later retry must never erase an earlier useful answer. Structured files or
    confirmation are strongest, followed by substantive chat text. Explicit
    execution failures rank below even a short partial answer.
    """
    raw = str(result or "").strip()
    if not raw:
        return 0
    payload = extract_worker_json_payload(raw)
    if isinstance(payload, dict):
        message = str(payload.get("message") or "").strip()
        confirmation = str(payload.get("confirmation") or payload.get("confirm") or "").strip()
        files = file_entries_from_json(payload)
        if is_no_reply_control(message) or is_no_reply_control(confirmation):
            return 1000
        if worker_result_is_explicit_failure(message):
            return -100 + min(len(message), 80)
        return (600 if files else 0) + (400 if confirmation else 0) + min(len(message), 300)
    if is_no_reply_control(raw):
        return 1000
    if worker_result_is_explicit_failure(raw):
        return -100 + min(len(raw), 80)
    return min(len(raw), 300)


def worker_result_is_infrastructure_failure(text: str) -> bool:
    markers = [
        "codex wrapper error:",
        "codex executable was not found",
        "executable not found:",
        "no such file or directory: 'codex'",
        'no such file or directory: "codex"',
        "returncode 127",
        "exit 127",
        "temporary failure in name resolution",
        "failed to lookup address information",
        "name or service not known",
        "network is unreachable",
        "transport channel closed",
        "failed to connect to websocket",
        "failed to connect to responses_websocket",
        "failed to refresh available models",
        "timeout waiting for child process to exit",
    ]
    return any(marker in text for marker in markers)


def worker_result_is_terminal_blocker(text: str) -> bool:
    blocker_markers = [
        "captcha",
        "login",
        "log in",
        "manual step",
        "manual confirmation",
        "waiting for approval",
        "waiting_confirmation",
        "approve continuation",
        "source-limited",
        "resend",
        "provide the exact",
        "exact file/source",
        "missing source",
        "not accessible",
        "需要登录",
        "需要人工",
        "需要确认",
        "请确认",
        "请重新发送",
        "缺少源文件",
        "找不到源文件",
    ]
    return any(marker in text for marker in blocker_markers)


def parse_worker_result(text: str) -> dict[str, Any]:
    if worker_result_is_private_backend_failure(text):
        return private_worker_failure_result(text)
    data = extract_worker_json_payload(text)
    if isinstance(data, dict):
        raw_message = str(data.get("message") or "")
        raw_confirmation = str(data.get("confirmation") or data.get("confirm") or "")
        no_reply = bool(data.get("no_reply")) or is_no_reply_control(raw_message) or is_no_reply_control(raw_confirmation)
        message = sanitize_worker_chat_message(raw_message)
        confirmation = sanitize_worker_chat_message(raw_confirmation)
        files = [] if json_payload_is_file_intake_receipt(data) else file_entries_from_json(data)
        return {
            "message": "" if is_no_reply_control(message) else message,
            "confirmation": "" if is_no_reply_control(confirmation) else confirmation,
            "files": files,
            "raw": text,
            "data": data,
            "no_reply": no_reply,
        }
    message_lines = []
    files = []
    for line in text.splitlines():
        if line.strip().upper().startswith("FILE:"):
            files.append(str(Path(line.split(":", 1)[1].strip()).expanduser()))
        else:
            message_lines.append(line)
    message = sanitize_worker_chat_message("\n".join(message_lines))
    no_reply = is_no_reply_control(message)
    return {"message": "" if no_reply else message, "confirmation": "", "files": files, "raw": text, "no_reply": no_reply}


def worker_result_is_private_backend_failure(text: str) -> bool:
    """Keep backend diagnostics in task state and out of user chat."""
    normalized = str(text or "").strip().lower()
    return bool(
        worker_result_is_infrastructure_failure(normalized)
        or normalized.startswith(
            (
                "worker failed via ",
                "worker failed before completion:",
                "codex failed:",
                "agent backend failed:",
            )
        )
    )


def private_worker_failure_result(text: str) -> dict[str, Any]:
    normalized = str(text or "").strip().lower()
    kind = (
        "transient_backend_unavailable"
        if worker_result_is_infrastructure_failure(normalized)
        else "backend_execution_failed"
    )
    return {
        "message": "",
        "confirmation": "",
        "files": [],
        "raw": str(text or ""),
        "no_reply": True,
        "private_failure": {"kind": kind},
    }


def terminal_worker_failure_feedback(
    task: dict[str, Any],
    result: dict[str, Any],
) -> str:
    """Return one quiet source-scoped receipt after all backends have failed."""
    if not isinstance(result.get("private_failure"), dict):
        return ""
    if task.get("terminal_failure_feedback"):
        return ""
    if is_isolated_scheduled_task(task):
        return ""
    source = task.get("source") if isinstance(task.get("source"), dict) else {}
    has_exact_source = any(
        source.get(key) not in (None, "")
        for key in (
            "local_id",
            "server_id",
            "message_id",
            "msg_id",
            "source_row_id",
        )
    )
    if not has_exact_source:
        return ""
    request_text = str(task.get("request") or "")
    if re.search(r"[\u3040-\u30ff]", request_text):
        return "このタスクは完了できませんでした。再試行は停止しており、重複送信はありません。"
    if re.search(r"[\u3400-\u9fff]", request_text):
        return "这次任务没有完成，已停止重试，不会重复发送。"
    return "This task did not complete. Retries have stopped, so it will not send duplicates."


def extract_worker_json_payload(text: str) -> dict[str, Any] | None:
    """Extract a worker JSON object even when a backend wraps it in logs.

    AgInTi and other fallback backends may print startup/progress logs before or
    after the real JSON result. The chat should receive only the structured
    `message`, `confirmation`, and `files`, not raw backend stdout.
    """
    stripped = text.strip()
    candidates = [stripped]
    for match in re.finditer(r"```(?:json)?\s*(\{.*?\})\s*```", stripped, flags=re.I | re.S):
        candidates.append(match.group(1).strip())
    decoder = json.JSONDecoder()
    for candidate in candidates:
        if not candidate:
            continue
        try:
            data = json.loads(candidate)
            if isinstance(data, dict):
                return data
        except Exception:
            pass
        for index, char in enumerate(candidate):
            if char != "{":
                continue
            try:
                data, _end = decoder.raw_decode(candidate[index:])
            except Exception:
                continue
            if isinstance(data, dict) and any(key in data for key in ("message", "confirmation", "confirm", "files", "artifacts")):
                return data
    return None


NOISY_BACKEND_LINE_PATTERNS = (
    re.compile(r"^\s*(?:\[.*?\]\s*)?(?:debug|trace|info|warn|warning|error)\b[:\s-]", re.I),
    re.compile(r"^\s*(?:running|executing|command|stdout|stderr|returncode|exit code)\b[:\s-]", re.I),
    re.compile(r"^\s*(?:aginti|codex|claude|backend|model|reasoning_effort|sandbox)\b[:\s-]", re.I),
    re.compile(r"^\s*[\w.-]+(?:\.py|\.sh)(?:\s|:)", re.I),
)


def sanitize_worker_chat_message(
    text: str, *, max_chars: int | None = None
) -> str:
    """Remove backend logs while preserving the complete human-facing text.

    ``max_chars`` remains accepted for older callers, but length management now
    belongs to the retry-safe delivery layer. Sanitization must never destroy
    answer content before that layer can split it or compile a PDF.
    """
    raw = str(text or "").strip()
    if not raw:
        return ""
    if is_no_reply_control(raw):
        return ""
    kept: list[str] = []
    dropped = 0
    for line in raw.splitlines():
        stripped = line.strip()
        if not stripped:
            if kept and kept[-1]:
                kept.append("")
            continue
        if any(pattern.search(stripped) for pattern in NOISY_BACKEND_LINE_PATTERNS):
            dropped += 1
            continue
        if stripped.startswith(("{", "}", '"backend"', '"stdout_tail"', '"stderr_tail"', '"returncode"')):
            dropped += 1
            continue
        kept.append(stripped)
    message = "\n".join(kept).strip()
    if is_no_reply_control(message):
        return ""
    return message


def json_payload_is_file_intake_receipt(data: dict[str, Any]) -> bool:
    nested = data.get("data") if isinstance(data.get("data"), dict) else {}
    return isinstance(nested.get("file_intake"), dict) and nested.get("require_file_delivery") is False


def file_entries_from_json(data: Any) -> list[str]:
    files: list[str] = []
    file_keys = {
        "file",
        "files",
        "path",
        "paths",
        "artifact",
        "artifacts",
        "attachment",
        "attachments",
        "image",
        "images",
        "video",
        "videos",
        "audio",
        "audios",
        "subtitle",
        "subtitles",
        "render",
        "renders",
        "preview",
        "previews",
    }

    def visit(value: Any, *, key: str = "") -> None:
        lowered = key.lower()
        if isinstance(value, str):
            keyed_as_file = lowered in file_keys or lowered.endswith(
                ("_file", "_path")
            )
            if keyed_as_file and looks_like_artifact_path(value):
                files.append(value)
        elif isinstance(value, list):
            for item in value:
                visit(item, key=key)
        elif isinstance(value, dict):
            for child_key, child_value in value.items():
                visit(child_value, key=str(child_key))

    visit(data)
    return unique_strings(files)


def upstream_feedback_entries(result: dict[str, Any]) -> list[dict[str, Any]]:
    """Extract bounded feedback proposals from one structured agent result."""
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    values: list[Any] = []
    if "upstream_feedback" in data:
        values.append(data.get("upstream_feedback"))
    nested = data.get("data") if isinstance(data.get("data"), dict) else {}
    if "upstream_feedback" in nested:
        values.append(nested.get("upstream_feedback"))
    entries: list[dict[str, Any]] = []
    for value in values:
        items = value if isinstance(value, list) else [value]
        for item in items:
            if isinstance(item, dict):
                entries.append(dict(item))
            if len(entries) >= 3:
                return entries
    return entries


def task_requests_feedback_report_delivery(task: dict[str, Any]) -> bool:
    """Require explicit file-delivery wording for a repository report."""
    text = task_focus_text(task).casefold()
    markers = (
        "send me the report file",
        "send the report file",
        "attach the report",
        "return the report file",
        "send this report back",
        "把报告文件发给我",
        "把報告文件發給我",
        "把这个报告发给我",
        "把這個報告發給我",
        "发送报告文件",
        "發送報告文件",
        "附上报告",
        "附上報告",
    )
    return any(marker in text for marker in markers)


def feedback_source_reference(task: dict[str, Any]) -> str:
    """Build a private source reference that the report writer hashes."""
    source = task.get("source") if isinstance(task.get("source"), dict) else {}
    payload = {
        "task_id": str(task.get("id") or ""),
        "transport": str(task.get("transport") or task.get("source_transport") or ""),
        "local_id": str(source.get("local_id") or ""),
        "server_id": str(source.get("server_id") or ""),
    }
    return json.dumps(payload, ensure_ascii=False, sort_keys=True)


def materialize_upstream_feedback(
    result: dict[str, Any],
    *,
    task: dict[str, Any] | None,
) -> dict[str, Any]:
    """Validate agent proposals and write privacy-safe local reports."""
    if not isinstance(task, dict):
        return result
    entries = upstream_feedback_entries(result)
    if not entries:
        return result

    src_root = ROOT / "src"
    src_text = str(src_root)
    if src_text not in sys.path:
        sys.path.insert(0, src_text)
    try:
        from agenticapp.feedback_ops import write_feedback_report
    except (ImportError, OSError) as exc:
        task["upstream_feedback_report_errors"] = [
            {"index": 0, "reason": f"feedback-writer-unavailable:{type(exc).__name__}"}
        ]
        return result

    reports: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    files = result.get("files") if isinstance(result.get("files"), list) else []
    for index, entry in enumerate(entries):
        target = str(entry.get("target") or "").strip().casefold()
        kind = str(entry.get("kind") or "").strip().casefold()
        title = str(entry.get("title") or "").strip()
        summary = str(entry.get("summary") or "").strip()
        expected = str(entry.get("expected") or "").strip()
        observed = str(entry.get("observed") or "").strip()
        evidence = entry.get("evidence") if isinstance(entry.get("evidence"), list) else []
        acceptance = (
            entry.get("acceptance")
            if isinstance(entry.get("acceptance"), list)
            else entry.get("acceptance_criteria")
            if isinstance(entry.get("acceptance_criteria"), list)
            else []
        )
        if entry.get("verified") is not True:
            errors.append({"index": index, "reason": "unverified"})
            continue
        if entry.get("transient") is True:
            errors.append({"index": index, "reason": "transient"})
            continue
        if not target or kind not in {"bug", "feature", "handoff"}:
            errors.append({"index": index, "reason": "invalid-target-or-kind"})
            continue
        if not title or not summary or not acceptance:
            errors.append({"index": index, "reason": "missing-required-content"})
            continue
        if kind == "bug" and (not observed or not evidence):
            errors.append({"index": index, "reason": "bug-needs-observation-and-evidence"})
            continue
        if kind == "feature" and not expected:
            errors.append({"index": index, "reason": "feature-needs-expected-behavior"})
            continue
        payload = {
            "target": target,
            "kind": kind,
            "title": title,
            "summary": summary,
            "expected": expected,
            "observed": observed,
            "evidence": evidence,
            "acceptance": acceptance,
            "workaround": entry.get("workaround"),
            "status": entry.get("status"),
            "verified": True,
            "transient": False,
            "source_ref": feedback_source_reference(task),
        }
        try:
            report = write_feedback_report(payload)
        except (OSError, ValueError) as exc:
            errors.append(
                {
                    "index": index,
                    "reason": f"write-failed:{type(exc).__name__}",
                }
            )
            continue
        safe_record = {
            key: report.get(key)
            for key in (
                "target",
                "kind",
                "report_id",
                "path",
                "created",
                "changed",
                "revision",
                "verified",
                "status",
            )
        }
        reports.append(safe_record)
        if (
            entry.get("deliver_report") is True
            and task_requests_feedback_report_delivery(task)
            and str(report.get("path") or "").strip()
        ):
            files.append(str(report["path"]))

    result["files"] = unique_strings([str(value) for value in files if str(value).strip()])
    if reports:
        data = result.get("data") if isinstance(result.get("data"), dict) else {}
        result["data"] = {**data, "upstream_feedback_reports": reports}
        task["upstream_feedback_reports"] = reports
    if errors:
        task["upstream_feedback_report_errors"] = errors
    return result


def prepare_result_files(
    result: dict[str, Any], raw_text: str, *, task: dict[str, Any] | None = None
) -> dict[str, Any]:
    if task is not None and is_passive_video_intake_task(task):
        guarded = canonical_passive_video_intake_result(task, result)
        raw_files = result.get("files") or []
        if not isinstance(raw_files, list):
            raw_files = [raw_files]
        rejected = unique_strings(
            [str(value) for value in raw_files if str(value).strip()]
            + extract_artifact_paths(raw_text)
        )
        if rejected:
            guarded["skipped_files"] = [
                {"path": value, "reason": "passive-video-save-only"}
                for value in rejected
            ]
        return guarded
    result = materialize_upstream_feedback(result, task=task)
    raw_files = result.get("files") or []
    if not isinstance(raw_files, list):
        raw_files = [raw_files]
    auto_files = [] if suppress_auto_artifact_extraction(result) else extract_artifact_paths(raw_text)
    candidates = unique_strings([
        *grant_auto_delivery_files(task),
        *shipinhao_auto_delivery_files(task),
        *raw_files,
        *auto_files,
    ])
    files: list[str] = []
    skipped: list[dict[str, str]] = []
    local_saved_paths: list[Path] = []
    downloads_root = local_downloads_dir()
    for candidate in candidates:
        path = resolve_candidate_path(candidate)
        if not path.exists():
            skipped.append({"path": candidate, "reason": "missing"})
            continue
        if task and task_requests_local_download_save(task):
            try:
                resolved = path.expanduser().resolve()
            except OSError:
                resolved = path
            if resolved == downloads_root or downloads_root in resolved.parents:
                local_saved_paths.append(resolved)
                skipped.append({"path": str(resolved), "reason": "local-save-no-chat-echo"})
                continue
        if (
            task
            and is_file_intake_task(task)
            and path in file_intake_source_artifact_paths(task)
            and not file_intake_source_delivery_requested(task)
        ):
            skipped.append({"path": str(path), "reason": "source-intake-echo"})
            continue
        ok, reason = is_safe_outbound_file(path)
        if not ok:
            skipped.append({"path": str(path), "reason": reason})
            continue
        if task_uses_aginti_fallback(task) and not is_current_task_artifact(path, task):
            skipped.append({"path": str(path), "reason": "aginti-unscoped-artifact"})
            continue
        delivery_path = ensure_meaningful_delivery_path(path, task)
        delivery_ok, delivery_reason = is_safe_outbound_file(delivery_path)
        if not delivery_ok:
            skipped.append({"path": str(delivery_path), "reason": delivery_reason})
            continue
        files.append(str(delivery_path))
    result["files"] = unique_strings(files)
    if local_saved_paths:
        saved = local_saved_paths[0]
        data = result.get("data") if isinstance(result.get("data"), dict) else {}
        result["data"] = {
            **data,
            "local_file_save": {
                "status": "completed",
                "verified": saved.is_file(),
                "target_path": str(saved),
                "filename": saved.name,
                "size_bytes": saved.stat().st_size if saved.is_file() else 0,
                "require_file_delivery": False,
            },
            "require_file_delivery": False,
        }
        if result_is_no_reply(result) or not str(result.get("message") or "").strip():
            result["message"] = f"已保存到 Downloads：{saved.name}。"
            result["confirmation"] = ""
            result["no_reply"] = False
    if skipped:
        result["skipped_files"] = skipped
    return result


PDF_INTERNAL_TRANSPORT_PATTERNS: tuple[tuple[re.Pattern[str], str], ...] = (
    (
        re.compile(r"\b(?:wecom|wechat):(?:external|internal|default|gui|group|dm)[^\s]*", re.I),
        "transport_identity",
    ),
    (
        re.compile(r"\b(?:wecom|wechat)-(?:inspiration|daily|task|worker)-[0-9A-Za-z_-]+", re.I),
        "internal_task_identity",
    ),
    (
        re.compile(r"/(?:home|workspace|var/tmp)/[^\s<>]+", re.I),
        "private_runtime_path",
    ),
    (
        re.compile(
            r"/tmp/(?:agenticapp|aginti|labcanvas|we(?:chat|com)|codex|task[-_]|"
            r"tmp[0-9A-Za-z_-]{6,})[^\s<>]*",
            re.I,
        ),
        "private_runtime_path",
    ),
    (
        re.compile(
            r"(?:最终群消息.{0,40}(?:字段|原文)|輸出契約|输出契约|"
            r"output\s+contract|delivery\s+contract)",
            re.I | re.S,
        ),
        "agent_output_contract",
    ),
    (
        re.compile(
            r"[\"“](?:message|files|confirmation|knowledge_items|upstream_feedback)[\"”]"
            r"\s*:\s*[\[{\"]",
            re.I,
        ),
        "raw_result_schema",
    ),
)

PDF_BROKEN_TEXT_RE = re.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f\ufffd]")
PDF_LAYOUT_AUDIT_VERSION = 1
PDF_FINAL_PAGE_MIN_BODY_CHARS = 220
PDF_PREVIOUS_PAGE_MIN_BODY_CHARS = 600
PDF_BASE14_FONT_NAMES = {
    "courier",
    "courier-bold",
    "courier-boldoblique",
    "courier-oblique",
    "helvetica",
    "helvetica-bold",
    "helvetica-boldoblique",
    "helvetica-oblique",
    "symbol",
    "times-bold",
    "times-bolditalic",
    "times-italic",
    "times-roman",
    "zapfdingbats",
}


def task_expects_reader_facing_pdf(task: dict[str, Any]) -> bool:
    """Limit content inspection to generated reports, not relayed source PDFs."""
    if task_forbids_chat_artifact_delivery(task) or task_is_grant_proposal(task):
        return False
    if is_file_intake_task(task):
        return False
    if task_is_research_summary(task) or isinstance(task.get("daily_research"), dict):
        return True
    if ".pdf" in task_required_artifact_suffixes(task):
        return True
    return request_explicitly_asks_for_file_delivery(task_focus_text(task)) and bool(
        re.search(r"(?:\bpdf\b|报告|報告|research\s+brief)", task_focus_text(task), re.I)
    )


def extract_pdf_text_for_quality(path: Path) -> tuple[str, str]:
    executable = shutil.which("pdftotext")
    if not executable:
        return "", "pdftotext_unavailable"
    try:
        completed = subprocess.run(
            [executable, "-layout", "-nopgbrk", str(path), "-"],
            check=False,
            capture_output=True,
            text=True,
            timeout=30,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return "", f"pdftotext_failed:{type(exc).__name__}"
    if completed.returncode != 0:
        return "", "pdftotext_failed"
    return completed.stdout, ""


def extract_pdf_page_texts_for_quality(path: Path) -> tuple[list[str], str]:
    """Extract page-preserving text for conservative layout checks."""
    executable = shutil.which("pdftotext")
    if not executable:
        return [], "pdftotext_unavailable"
    try:
        completed = subprocess.run(
            [executable, "-layout", str(path), "-"],
            check=False,
            capture_output=True,
            text=True,
            timeout=30,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return [], f"pdftotext_pages_failed:{type(exc).__name__}"
    if completed.returncode != 0:
        return [], "pdftotext_pages_failed"
    pages = completed.stdout.split("\f")
    while pages and not pages[-1].strip():
        pages.pop()
    return pages, ""


def analyze_pdf_font_embedding(path: Path) -> dict[str, Any]:
    """Find non-embedded fonts that can render clean text as missing glyph boxes."""
    executable = shutil.which("pdffonts")
    if not executable:
        return {
            "status": "unavailable",
            "error": "pdffonts_unavailable",
            "font_count": 0,
            "unembedded_fonts": [],
        }
    try:
        completed = subprocess.run(
            [executable, str(path)],
            check=False,
            capture_output=True,
            text=True,
            timeout=30,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {
            "status": "unavailable",
            "error": f"pdffonts_failed:{type(exc).__name__}",
            "font_count": 0,
            "unembedded_fonts": [],
        }
    if completed.returncode != 0:
        return {
            "status": "unavailable",
            "error": "pdffonts_failed",
            "font_count": 0,
            "unembedded_fonts": [],
        }
    rows: list[tuple[str, str]] = []
    for line in completed.stdout.splitlines():
        fields = line.split()
        if (
            len(fields) < 7
            or not all(
                value.casefold() in {"yes", "no"}
                for value in fields[-5:-2]
            )
            or not all(value.isdigit() for value in fields[-2:])
        ):
            continue
        rows.append((fields[0], fields[-5]))
    if not rows:
        return {
            "status": "unavailable",
            "error": "pdffonts_empty",
            "font_count": 0,
            "unembedded_fonts": [],
        }
    unembedded: list[str] = []
    for raw_name, raw_embedded in rows:
        name = re.sub(r"^[A-Z]{6}\+", "", raw_name).casefold()
        embedded = raw_embedded.strip().casefold()
        if embedded != "yes" and name not in PDF_BASE14_FONT_NAMES:
            unembedded.append(raw_name)
    return {
        "status": "checked",
        "error": "",
        "font_count": len(rows),
        "unembedded_fonts": unique_strings(unembedded),
    }


def pdf_page_body_text(page_text: str) -> str:
    """Remove the known running header/footer before measuring page substance."""
    body_lines: list[str] = []
    for raw_line in page_text.splitlines():
        line = re.sub(r"\s+", " ", raw_line).strip()
        if not line:
            continue
        if "LABCANVAS RESEARCH BRIEF" in line:
            continue
        if re.fullmatch(r"\d{1,4}", line):
            continue
        if re.fullmatch(
            r"(?:January|February|March|April|May|June|July|August|September|"
            r"October|November|December)\s+\d{1,2},\s+\d{4}",
            line,
            flags=re.I,
        ):
            continue
        body_lines.append(line)
    return "\n".join(body_lines)


def analyze_pdf_layout_for_quality(path: Path) -> dict[str, Any]:
    """Detect blank pages and tiny terminal pages without imposing page counts."""
    pages, error = extract_pdf_page_texts_for_quality(path)
    if error:
        return {
            "version": PDF_LAYOUT_AUDIT_VERSION,
            "status": "unavailable",
            "error": error,
            "page_count": 0,
            "page_body_char_counts": [],
            "issues": [],
        }
    body_char_counts = [
        len(re.sub(r"\s+", "", pdf_page_body_text(page)))
        for page in pages
    ]
    issues: list[str] = []
    if any(count < 24 for count in body_char_counts):
        issues.append("blank_or_nearly_blank_pdf_page")
    if (
        len(body_char_counts) >= 3
        and body_char_counts[-1] < PDF_FINAL_PAGE_MIN_BODY_CHARS
        and body_char_counts[-2] >= PDF_PREVIOUS_PAGE_MIN_BODY_CHARS
        and body_char_counts[-1] * 3 < body_char_counts[-2]
    ):
        issues.append("orphan_final_pdf_page")
    return {
        "version": PDF_LAYOUT_AUDIT_VERSION,
        "status": "checked",
        "error": "",
        "page_count": len(pages),
        "page_body_char_counts": body_char_counts,
        "issues": unique_strings(issues),
    }


def task_requires_pdf_render_audit(task: dict[str, Any]) -> bool:
    execution = (
        task.get("execution_contract")
        if isinstance(task.get("execution_contract"), dict)
        else {}
    )
    report_quality = (
        execution.get("report_quality")
        if isinstance(execution.get("report_quality"), dict)
        else {}
    )
    required = {
        str(item or "").strip().casefold()
        for item in execution.get("required_artifacts") or []
        if str(item or "").strip()
    }
    return bool(report_quality.get("independent_review_before_delivery")) or (
        "render_audit" in required
    )


def persist_pdf_render_audit(
    task: dict[str, Any],
    path: Path,
    layout: dict[str, Any],
) -> dict[str, Any]:
    """Persist page previews and a private audit manifest for generated reports."""
    if (
        not task_requires_pdf_render_audit(task)
        or not path.is_file()
        or path.stat().st_size <= 0
    ):
        return {}
    audit_dir = path.parent / f"{path.stem}-render-audit"
    audit_dir.mkdir(parents=True, exist_ok=True)
    manifest_path = audit_dir / "render-audit.json"
    source_signature = {
        "filename": path.name,
        "bytes": path.stat().st_size,
        "mtime_ns": path.stat().st_mtime_ns,
    }
    try:
        existing = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        existing = {}
    if (
        isinstance(existing, dict)
        and existing.get("version") == PDF_LAYOUT_AUDIT_VERSION
        and existing.get("source") == source_signature
        and existing.get("render_status") == "rendered"
        and len(existing.get("rendered_pages") or [])
        == int(existing.get("page_count") or 0)
        and bool(existing.get("rendered_pages"))
        and all(
            (audit_dir / str(name)).is_file()
            for name in existing.get("rendered_pages") or []
        )
    ):
        return {**existing, "manifest_path": str(manifest_path.resolve())}

    for stale in audit_dir.glob("page-*.png"):
        stale.unlink(missing_ok=True)
    rendered_pages: list[str] = []
    render_status = "unavailable"
    render_error = "pdftoppm_unavailable"
    renderer = shutil.which("pdftoppm")
    if renderer:
        prefix = audit_dir / "page"
        try:
            completed = subprocess.run(
                [renderer, "-png", "-r", "110", str(path), str(prefix)],
                check=False,
                capture_output=True,
                text=True,
                timeout=90,
            )
            rendered_pages = [item.name for item in sorted(audit_dir.glob("page-*.png"))]
            if completed.returncode == 0 and len(rendered_pages) == int(layout.get("page_count") or 0):
                render_status = "rendered"
                render_error = ""
            else:
                render_status = "failed"
                render_error = "pdftoppm_failed"
        except (OSError, subprocess.TimeoutExpired) as exc:
            render_status = "failed"
            render_error = f"pdftoppm_failed:{type(exc).__name__}"
    manifest = {
        "version": PDF_LAYOUT_AUDIT_VERSION,
        "source": source_signature,
        "checked_at": datetime.now().isoformat(timespec="seconds"),
        "layout_status": str(layout.get("status") or ""),
        "page_count": int(layout.get("page_count") or 0),
        "page_body_char_counts": list(layout.get("page_body_char_counts") or []),
        "issues": list(layout.get("issues") or []),
        "render_status": render_status,
        "render_error": render_error,
        "rendered_pages": rendered_pages,
    }
    tmp_manifest = manifest_path.with_suffix(".tmp")
    tmp_manifest.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    tmp_manifest.replace(manifest_path)
    return {**manifest, "manifest_path": str(manifest_path.resolve())}


def reader_facing_pdf_quality_issues(
    task: dict[str, Any],
    path: Path,
    *,
    layout_audit: dict[str, Any] | None = None,
    font_audit: dict[str, Any] | None = None,
) -> list[str]:
    """Reject generated reports that are unreadable or expose orchestration internals."""
    if not task_expects_reader_facing_pdf(task):
        return []
    if not path.is_file() or path.stat().st_size <= 0:
        return ["missing_or_empty_pdf"]
    text, extraction_error = extract_pdf_text_for_quality(path)
    if extraction_error:
        return [extraction_error]
    compact = re.sub(r"\s+", " ", text).strip()
    issues: list[str] = []
    if len(compact) < 320:
        issues.append("insufficient_reader_facing_content")
    if PDF_BROKEN_TEXT_RE.search(text):
        issues.append("broken_text_extraction")
    layout = layout_audit or analyze_pdf_layout_for_quality(path)
    issues.extend(str(item) for item in layout.get("issues") or [])
    fonts = font_audit or analyze_pdf_font_embedding(path)
    if fonts.get("status") == "checked" and fonts.get("unembedded_fonts"):
        issues.append("unembedded_nonbase_pdf_fonts")
    for pattern, label in PDF_INTERNAL_TRANSPORT_PATTERNS:
        if pattern.search(text):
            issues.append(label)
    execution = (
        task.get("execution_contract")
        if isinstance(task.get("execution_contract"), dict)
        else {}
    )
    evidence_contract = (
        execution.get("research_evidence")
        if isinstance(execution.get("research_evidence"), dict)
        else {}
    )
    evidence: dict[str, Any] = {}
    if bool(evidence_contract.get("required")):
        if len(compact) < 900:
            issues.append("insufficient_substantive_research_content")
        evidence = research_report_evidence_summary(text)
        if evidence["has_unresolved_citations"]:
            issues.append("unresolved_report_citations")
        minimum_sources = max(
            1,
            int(evidence_contract.get("minimum_traceable_sources") or 2),
        )
        if evidence["traceable_source_count"] < minimum_sources:
            issues.append("insufficient_traceable_research_sources")
        if not evidence["has_evidence_section"]:
            issues.append("missing_reader_evidence_section")
        if bool(evidence_contract.get("state_uncertainty_and_limitations")) and not evidence[
            "has_uncertainty"
        ]:
            issues.append("missing_uncertainty_or_limitations")
        if bool(evidence_contract.get("include_actionable_next_steps")) and not evidence[
            "has_actionable_next_steps"
        ]:
            issues.append("missing_actionable_next_steps")
        manifest = load_task_research_evidence_manifest(task)
        if manifest:
            allowed_identifiers = {
                str(item)
                for item in manifest.get("allowed_reference_identifiers") or []
                if str(item).strip()
            }
            report_identifiers = set(evidence.get("reference_identifiers") or [])
            if report_identifiers - allowed_identifiers:
                issues.append("unverified_report_reference")
            manifest_sources = [
                item
                for item in manifest.get("sources") or []
                if isinstance(item, dict)
            ]
            if manifest_sources:
                matched_source_count = sum(
                    bool(
                        report_identifiers
                        & {
                            str(identifier)
                            for identifier in item.get("reference_identifiers") or []
                            if str(identifier).strip()
                        }
                    )
                    for item in manifest_sources
                )
            else:
                matched_source_count = len(report_identifiers & allowed_identifiers)
            if matched_source_count < minimum_sources:
                issues.append("insufficient_verified_research_sources")
    report_quality = (
        execution.get("report_quality")
        if isinstance(execution.get("report_quality"), dict)
        else {}
    )
    required_dimensions = {
        str(item or "").strip().casefold()
        for item in report_quality.get("required_dimensions") or []
        if str(item or "").strip()
    }
    if required_dimensions:
        if not evidence:
            evidence = research_report_evidence_summary(text)
        if (
            "source_level_methods_results_and_limitations" in required_dimensions
            and not (
                evidence["has_methods_detail"]
                and evidence["has_results_detail"]
                and evidence["has_uncertainty"]
            )
        ):
            issues.append("missing_source_level_methods_results_limits")
        if (
            "cross_source_synthesis_and_tensions" in required_dimensions
            and not evidence["has_cross_source_synthesis"]
        ):
            issues.append("missing_cross_source_synthesis")
        if (
            "evidence_boundaries_and_uncertainty" in required_dimensions
            and not evidence["has_uncertainty"]
        ):
            issues.append("missing_evidence_boundaries")
        if (
            "actionable_experiments_or_decisions" in required_dimensions
            and not evidence["has_actionable_next_steps"]
        ):
            issues.append("missing_actionable_experiments_or_decisions")
        if (
            "complete_traceable_references" in required_dimensions
            and not evidence["has_reference_section"]
        ):
            issues.append("missing_complete_reference_section")
    return unique_strings(issues)


def normalize_pdf_quality_rejections(value: Any) -> list[dict[str, Any]]:
    """Normalize current and legacy rejection records by exact PDF path."""
    merged: dict[str, dict[str, Any]] = {}
    for item in value or []:
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or item.get("workspace_path") or "").strip()
        issues = unique_strings(
            str(issue).strip()
            for issue in item.get("issues") or []
            if str(issue).strip()
        )
        if not raw_path or not issues:
            continue
        path = str(Path(raw_path).expanduser().resolve())
        current = merged.setdefault(
            path,
            {
                "path": path,
                "filename": str(item.get("filename") or Path(path).name),
                "issues": [],
            },
        )
        current["issues"] = unique_strings([*current["issues"], *issues])
    return list(merged.values())


def task_pdf_quality_rejections(
    task: dict[str, Any],
    *,
    rediscover: bool = False,
) -> list[dict[str, Any]]:
    """Return durable PDF repair evidence across legacy and failed retries."""
    candidates: list[dict[str, Any]] = []
    for item in task.get("pdf_quality_rejections") or []:
        if isinstance(item, dict):
            candidates.append(item)

    result = task.get("result") if isinstance(task.get("result"), dict) else {}
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    nested = data.get("data") if isinstance(data.get("data"), dict) else {}
    for payload in (data, nested):
        for item in payload.get("pdf_quality_rejections") or []:
            if isinstance(item, dict):
                candidates.append(item)

    repair = (
        task.get("completion_audit_repair")
        if isinstance(task.get("completion_audit_repair"), dict)
        else {}
    )
    artifact_repair = (
        repair.get("artifact_repair")
        if isinstance(repair.get("artifact_repair"), dict)
        else {}
    )
    for item in artifact_repair.get("rejected_artifacts") or []:
        if isinstance(item, dict):
            candidates.append(item)

    normalized = normalize_pdf_quality_rejections(candidates)
    if not rediscover or not task_expects_reader_facing_pdf(task):
        return normalized

    artifact_root = Path(
        str(task.get("artifact_dir") or worker_artifact_dir(task))
    ).expanduser().resolve()
    if not artifact_root.is_dir():
        return normalized
    rediscovered: list[dict[str, Any]] = []
    inspected: set[Path] = set()
    for item in normalized:
        path = Path(str(item.get("path") or "")).expanduser().resolve()
        if not path.is_file() or not path.is_relative_to(artifact_root):
            rediscovered.append(item)
            continue
        inspected.add(path)
        issues = reader_facing_pdf_quality_issues(task, path)
        if issues:
            rediscovered.append(
                {
                    "path": str(path),
                    "filename": path.name,
                    "issues": issues,
                }
            )
    for path in sorted(artifact_root.glob("*.pdf")):
        path = path.resolve()
        if path in inspected:
            continue
        issues = reader_facing_pdf_quality_issues(task, path)
        if issues:
            rediscovered.append(
                {
                    "path": str(path.resolve()),
                    "filename": path.name,
                    "issues": issues,
                }
            )
    return normalize_pdf_quality_rejections(rediscovered)


def enforce_reader_facing_pdf_quality(
    task: dict[str, Any], result: dict[str, Any]
) -> dict[str, Any]:
    """Withhold invalid report PDFs so completion audit can repair them once."""
    if not task_expects_reader_facing_pdf(task):
        return result
    kept: list[str] = []
    rejected: list[dict[str, Any]] = []
    render_audits: list[dict[str, Any]] = []
    inspected_pdf = False
    for raw in result.get("files") or []:
        path = Path(str(raw)).expanduser().resolve()
        if path.suffix.casefold() != ".pdf":
            kept.append(str(path))
            continue
        inspected_pdf = True
        layout = analyze_pdf_layout_for_quality(path)
        font_audit = analyze_pdf_font_embedding(path)
        issues = reader_facing_pdf_quality_issues(
            task,
            path,
            layout_audit=layout,
            font_audit=font_audit,
        )
        render_audit = persist_pdf_render_audit(task, path, layout)
        if render_audit:
            render_audit["font_audit"] = font_audit
            render_audits.append(render_audit)
        if issues:
            rejected.append(
                {
                    "path": str(path),
                    "filename": path.name,
                    "issues": issues,
                }
            )
        else:
            kept.append(str(path))
    guarded = dict(result)
    guarded["files"] = unique_strings(kept)
    data = guarded.get("data") if isinstance(guarded.get("data"), dict) else {}
    guarded["data"] = {
        **data,
        "pdf_quality_rejections": rejected,
        "pdf_render_audits": render_audits,
    }
    if rejected:
        task["pdf_quality_rejections"] = rejected
        skipped = list(guarded.get("skipped_files") or [])
        skipped.extend(
            {
                "path": item["path"],
                "reason": "reader-facing-pdf-quality:" + ",".join(item["issues"]),
            }
            for item in rejected
        )
        guarded["skipped_files"] = skipped
    elif inspected_pdf:
        task.pop("pdf_quality_rejections", None)
    return guarded


