def ensure_meaningful_delivery_path(
    path: Path, task: dict[str, Any] | None
) -> Path:
    """Give generic generated artifacts a stable recipient-facing basename.

    Exact inbound files keep their original identity. Generated content is
    hard-linked into the task's ignored artifact directory when possible, with
    a copy fallback for cross-filesystem outputs. The source file is untouched.
    """
    resolved = path.expanduser().resolve()
    if not isinstance(task, dict) or not str(task.get("artifact_dir") or "").strip():
        return resolved
    if resolved in file_intake_source_artifact_paths(task):
        return resolved
    if not artifact_name_needs_delivery_alias(resolved.name, task):
        return resolved

    delivery_dir = Path(str(task["artifact_dir"])).expanduser().resolve() / "delivery"
    delivery_dir.mkdir(parents=True, exist_ok=True)

    def same_content(candidate: Path) -> bool:
        try:
            if candidate.samefile(resolved):
                return True
        except OSError:
            pass
        try:
            return (
                candidate.is_file()
                and candidate.stat().st_size == resolved.stat().st_size
                and sha256_file(candidate) == sha256_file(resolved)
            )
        except OSError:
            return False

    aliases = task.setdefault("delivery_artifact_aliases", [])
    if not isinstance(aliases, list):
        aliases = []
        task["delivery_artifact_aliases"] = aliases
    for item in aliases:
        if not isinstance(item, dict) or str(item.get("source") or "") != str(resolved):
            continue
        prior = Path(str(item.get("delivery") or "")).expanduser()
        if same_content(prior):
            return prior.resolve()

    basename = meaningful_delivery_basename(resolved, task)
    destination = delivery_dir / basename
    version = 2
    while destination.exists():
        if same_content(destination):
            if not any(
                isinstance(item, dict)
                and str(item.get("source") or "") == str(resolved)
                and str(item.get("delivery") or "") == str(destination.resolve())
                for item in aliases
            ):
                aliases.append(
                    {
                        "source": str(resolved),
                        "delivery": str(destination.resolve()),
                        "display_name": destination.name,
                    }
                )
            return destination.resolve()
        destination = delivery_dir / f"{Path(basename).stem}-v{version}{resolved.suffix.lower()}"
        version += 1

    try:
        os.link(resolved, destination)
    except OSError:
        try:
            shutil.copy2(resolved, destination)
        except OSError as exc:
            task.setdefault("artifact_filename_warnings", []).append(
                {
                    "source": str(resolved),
                    "reason": f"delivery-alias-failed:{type(exc).__name__}",
                }
            )
            return resolved

    aliases.append(
        {
            "source": str(resolved),
            "delivery": str(destination.resolve()),
            "display_name": destination.name,
        }
    )
    return destination.resolve()


def artifact_name_needs_delivery_alias(
    filename: str, task: dict[str, Any] | None = None
) -> bool:
    stem = Path(str(filename or "")).stem.casefold()
    normalized = re.sub(r"[^0-9a-z]+", "-", stem).strip("-")
    unicode_normalized = re.sub(r"[^\w]+", "-", stem, flags=re.UNICODE).strip("-_")
    compact_label = re.sub(r"[\W_]+", "", stem, flags=re.UNICODE)
    normalized_tokens = [token for token in unicode_normalized.split("-") if token]
    operational_only = bool(normalized_tokens) and all(
        token in GENERIC_DELIVERY_STEMS
        or re.sub(r"[\W_]+", "", token, flags=re.UNICODE) in GENERIC_DELIVERY_LABELS
        or token in {"complete", "completed", "final", "latest", "new"}
        or bool(re.fullmatch(r"v?\d+", token))
        for token in normalized_tokens
    )
    if (
        normalized in GENERIC_DELIVERY_STEMS
        or compact_label in GENERIC_DELIVERY_LABELS
        or operational_only
    ):
        return True
    if re.fullmatch(r"(?:task|job|run)?-?[0-9a-f]{12,}", normalized):
        return True
    if re.fullmatch(
        r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",
        normalized,
    ):
        return True
    if re.match(r"^(20\d{2}-\d{2}-\d{2})-\1(?:-|$)", unicode_normalized):
        return True
    if re.search(r"(?:^|-)(?:one-exact|exact-task|task-scoped)(?:-|$)", normalized):
        return True
    if isinstance(task, dict):
        task_id = safe_slug(str(task.get("id") or ""))
        if task_id != "task" and (
            normalized == task_id or normalized.startswith(f"{task_id}-")
        ):
            return True
    return False


def meaningful_delivery_basename(path: Path, task: dict[str, Any]) -> str:
    suffix = path.suffix.lower()
    subject = task_artifact_subject(task)
    role = DELIVERY_ROLE_BY_SUFFIX.get(suffix, "artifact")
    parts = [task_artifact_date(task), subject]
    if role not in subject.casefold():
        parts.append(role)
    stem = "-".join(part for part in parts if part).strip("-.")
    return f"{stem[:120].rstrip('-._') or 'labcanvas-artifact'}{suffix}"


def task_artifact_date(task: dict[str, Any]) -> str:
    source = task.get("source") if isinstance(task.get("source"), dict) else {}
    candidates = [
        task.get("created_at"),
        task.get("enqueued_at"),
        source.get("created_at"),
        source.get("timestamp"),
    ]
    for candidate in candidates:
        match = re.search(
            r"(?<!\d)(20\d{2})[-/]?(\d{2})[-/]?(\d{2})(?!\d)",
            str(candidate or ""),
        )
        if match:
            return f"{match.group(1)}-{match.group(2)}-{match.group(3)}"
    return datetime.now().strftime("%Y-%m-%d")


def task_artifact_subject(task: dict[str, Any]) -> str:
    route = task.get("route_decision") if isinstance(task.get("route_decision"), dict) else {}
    daily = task.get("daily_research") if isinstance(task.get("daily_research"), dict) else {}
    daily_topics = daily.get("topics") if isinstance(daily.get("topics"), list) else []
    candidates = [
        task.get("artifact_subject"),
        route.get("artifact_subject"),
        daily.get("topic"),
        daily_topics[0] if daily_topics else "",
        task.get("request"),
        route.get("topic"),
        route.get("title"),
        task.get("chat"),
    ]
    for candidate in candidates:
        subject = human_filename_subject(str(candidate or ""))
        if subject:
            return subject
    return "labcanvas"


def human_filename_subject(value: str) -> str:
    text = re.sub(r"https?://\S+", " ", str(value or ""))
    text = re.sub(r"/[A-Za-z0-9_.@%+=,:/-]+", " ", text)
    lines = []
    ignored_labels = {
        "current coalesced request",
        "current request",
        "request",
        "context",
        "task",
    }
    for raw in text.splitlines():
        line = raw.strip().strip("`#>*- ")
        if not line or line.rstrip(":").casefold() in ignored_labels:
            continue
        lines.append(line)
    text = " ".join(lines) if lines else text
    text = re.sub(
        r"^(?:please|could you|can you|would you|kindly|help me|i want you to)\s+",
        "",
        text,
        flags=re.IGNORECASE,
    )
    for phrase in ("请帮我", "請幫我", "请", "請", "帮我", "幫我", "可以帮我", "可以幫我"):
        if text.startswith(phrase):
            text = text[len(phrase) :].lstrip()
            break
    text = re.sub(
        r"\b(?:create|generate|make|write|send|return|give|prepare|provide|the|a|an|"
        r"please|concise|detailed|final|file|pdf|report|result|output)\b",
        " ",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"(?:生成|创建|創建|制作|製作|发送|發送|报告|報告|文件|结果|結果)", " ", text)
    text = re.sub(r"\b[0-9a-f]{12,}\b", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"[^\w\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af.-]+", "-", text, flags=re.UNICODE)
    text = re.sub(r"[-_.]{2,}", "-", text).strip("-._")
    if not text:
        return ""
    return text[:48].rstrip("-._").casefold()


def file_intake_source_artifact_paths(task: dict[str, Any]) -> set[Path]:
    """Return task-scoped copies of the exact inbound attachment."""
    preflight = task.get("preflight") if isinstance(task.get("preflight"), dict) else {}
    paths: set[Path] = set()
    for section_name in ("file_intake", "media_resolution"):
        section = preflight.get(section_name) if isinstance(preflight.get(section_name), dict) else {}
        for item in section.get("copied") or []:
            if not isinstance(item, dict):
                continue
            for key in ("task_copy_path", "saved_path", "source_path", "mirror_path"):
                raw = str(item.get(key) or "").strip()
                if not raw:
                    continue
                try:
                    paths.add(Path(raw).expanduser().resolve())
                except OSError:
                    continue
    return paths


def file_intake_source_delivery_requested(task: dict[str, Any]) -> bool:
    """Require an explicit request before returning the uploaded source file."""
    text = task_focus_text(task).casefold()
    markers = (
        "send this file back",
        "send the original file",
        "return this file",
        "return the original",
        "forward this file",
        "resend this file",
        "把这个文件发回",
        "把這個文件發回",
        "发回原文件",
        "發回原文件",
        "转发这个文件",
        "轉發這個文件",
        "重新发这个文件",
        "重新發這個文件",
    )
    return any(marker in text for marker in markers)


def task_uses_aginti_fallback(task: dict[str, Any] | None) -> bool:
    if not isinstance(task, dict):
        return False
    session = task.get("agent_session")
    return isinstance(session, dict) and str(session.get("backend") or "").casefold() == "aginti"


def is_current_task_artifact(path: Path, task: dict[str, Any] | None) -> bool:
    if not isinstance(task, dict):
        return False
    raw_root = str(task.get("artifact_dir") or "").strip()
    if not raw_root:
        return False
    try:
        root = Path(raw_root).expanduser().resolve()
        resolved = path.expanduser().resolve()
    except OSError:
        return False
    return resolved == root or root in resolved.parents


def suppress_auto_artifact_extraction(result: dict[str, Any]) -> bool:
    data = result_delivery_data(result)
    if not isinstance(data.get("file_intake"), dict):
        return False
    return data.get("require_file_delivery") is False


def result_is_file_intake_receipt(result: dict[str, Any]) -> bool:
    data = result_delivery_data(result)
    return isinstance(data.get("file_intake"), dict) and data.get("require_file_delivery") is False


def result_delivery_data(result: dict[str, Any]) -> dict[str, Any]:
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    nested = data.get("data") if isinstance(data.get("data"), dict) else {}
    if "file_intake" in nested or "require_file_delivery" in nested:
        return nested
    return data


def extract_artifact_paths(text: str) -> list[str]:
    candidates: list[str] = []
    scan_text = re.sub(r"https?://\S+", " ", str(text or ""))
    absolute = r"(?<![:/])/[A-Za-z0-9_./:@%+=,\-]+"
    relative = r"(?:output|cad|pcb|publications|references|examples)/[A-Za-z0-9_./:@%+=,\-]+"
    for match in re.finditer(f"(?:{absolute}|{relative})", scan_text):
        token = clean_path_token(match.group(0))
        if looks_like_artifact_path(token):
            candidates.append(token)
    return unique_strings(candidates)


def looks_like_artifact_path(value: str) -> bool:
    token = clean_path_token(value)
    return bool(token and Path(token).suffix.lower() in OUTBOUND_SUFFIXES)


def clean_path_token(value: str) -> str:
    return str(value or "").strip().strip("\"'`").rstrip(".,;:)]}>")


def resolve_candidate_path(value: str) -> Path:
    path = Path(clean_path_token(value)).expanduser()
    if not path.is_absolute():
        path = ROOT / path
    return path.resolve()


def is_safe_outbound_file(path: Path) -> tuple[bool, str]:
    resolved = path.resolve()
    if not resolved.is_file():
        return False, "not-a-file"
    if resolved.suffix.lower() not in OUTBOUND_SUFFIXES:
        return False, "unsupported-suffix"
    if ".private" in resolved.parts or resolved == PRIVATE or PRIVATE in resolved.parents:
        return False, "private-path"
    lower_name = resolved.name.casefold()
    internal_evidence_names = {
        "routine_contract.json",
        "routine_contract.md",
        "same_chat_interruptions.json",
        "media_resolution_manifest.json",
        "file_intake_manifest.json",
        "finder_feed_request.private.json",
        "finder_network_capture.private.json",
    }
    if lower_name in internal_evidence_names or ".private." in lower_name:
        return False, "internal-evidence"
    private_markers = {"wechat_decrypt", "xwechat_files", "cookies", "session", "tokens", "keys"}
    if any(marker in part.lower() for part in resolved.parts for marker in private_markers):
        return False, "sensitive-path"
    max_bytes = int(os.environ.get("WECHAT_WORKER_MAX_OUTBOUND_BYTES", DEFAULT_MAX_OUTBOUND_BYTES))
    try:
        if resolved.stat().st_size > max_bytes:
            return False, "too-large"
    except OSError:
        return False, "stat-failed"
    return True, ""


def unique_strings(values: list[str]) -> list[str]:
    result: list[str] = []
    seen: set[str] = set()
    for value in values:
        item = str(value or "").strip()
        if not item or item in seen:
            continue
        seen.add(item)
        result.append(item)
    return result


def gui_search_allowed_for_target(target: dict[str, Any]) -> bool:
    return bool(target.get("allow_search", False))


def send_message(
    message: str,
    chat: str,
    send_targets: Path,
    *,
    target: dict[str, Any] | None = None,
    task: dict[str, Any] | None = None,
) -> None:
    message = sanitize_chat_visible_text(message)
    target = target if target is not None else guarded_send_target(chat, send_targets)
    if target:
        transport = os.environ.get("WECHAT_WORKER_TEXT_TRANSPORT", "auto").strip().casefold()
        if transport not in {"auto", "android", "desktop"}:
            raise RuntimeError(
                "Unsupported WECHAT_WORKER_TEXT_TRANSPORT; expected auto, android, or desktop"
            )
        task_id = str((task or {}).get("id") or f"adhoc-text-{time.time_ns()}")
        if transport == "android":
            run_android_wechat_sender(
                chat=chat,
                target=target,
                task_id=task_id,
                messages=[message],
            )
            return
        command = [
            sys.executable,
            str(ROOT / "agentic_tools" / "wechat_gui_agent" / "scripts" / "wechat_gui_send.py"),
            "--targets-file",
            "",
            "--send",
            "--prefer-current",
            "--pause",
            os.environ.get("WECHAT_WORKER_SEND_PAUSE", "0.35"),
            "--mirror-db",
            str(DEFAULT_DB),
        ]
        with tempfile.NamedTemporaryFile("w+", suffix=".json", encoding="utf-8", delete=False) as handle:
            target_file = Path(handle.name)
            json.dump({"message": message, "targets": [target]}, handle, ensure_ascii=False)
        command[command.index("--targets-file") + 1] = str(target_file)
        if gui_search_allowed_for_target(target):
            command.append("--allow-search")
        else:
            command.append("--no-search")
        try:
            try:
                run_send_subprocess(command)
            except RuntimeError as exc:
                if transport != "auto" or not desktop_message_can_fallback_to_android(exc):
                    raise
                run_android_wechat_sender(
                    chat=chat,
                    target=target,
                    task_id=task_id,
                    messages=[message],
                )
        finally:
            target_file.unlink(missing_ok=True)
        return
    if os.environ.get("WECHAT_ALLOW_UNGUARDED_SEND", "0") != "1":
        raise RuntimeError(f"Refusing unguarded WeChat message send for {chat}: missing send_target")
    subprocess.run(
        [
            sys.executable,
            str(ROOT / "agentic_tools" / "wechat_gui_agent" / "scripts" / "wechat_chatops_bridge.py"),
            "--config",
            str(PRIVATE / "lazy-research-chatops.local.json"),
            "--chat",
            chat,
            "--message",
            message,
        ],
        cwd=ROOT,
        check=False,
    )


def desktop_message_can_fallback_to_android(exc: BaseException) -> bool:
    """Fail over only when desktop preflight proves no message was submitted."""
    message = str(exc).casefold()
    return any(
        marker in message
        for marker in (
            "wechat_entry_required",
            "no visible wechat window found",
        )
    )


def send_file(
    file_path: Path,
    chat: str,
    send_targets: Path,
    *,
    target: dict[str, Any] | None = None,
    task: dict[str, Any] | None = None,
) -> None:
    ok, reason = is_safe_outbound_file(file_path)
    if not ok:
        raise ValueError(f"Refusing outbound file {file_path}: {reason}")
    target = target if target is not None else guarded_send_target(chat, send_targets)
    if target:
        transport = os.environ.get("WECHAT_WORKER_FILE_TRANSPORT", "android").strip().casefold()
        if transport == "android":
            try:
                run_android_wechat_sender(
                    chat=chat,
                    target=target,
                    task_id=str((task or {}).get("id") or f"adhoc-{time.time_ns()}"),
                    files=[file_path],
                )
                transport_name = "wechat_android"
            except RuntimeError as exc:
                if not android_file_send_can_fallback_to_desktop(exc):
                    raise
                run_desktop_wechat_file_sender(file_path, target)
                transport_name = "wechat_gui_after_android_preflight_failure"
        elif transport == "desktop":
            run_desktop_wechat_file_sender(file_path, target)
            transport_name = "wechat_gui"
        else:
            raise RuntimeError(
                "Unsupported WECHAT_WORKER_FILE_TRANSPORT; expected android or desktop"
            )
    else:
        if os.environ.get("WECHAT_ALLOW_UNGUARDED_SEND", "0") != "1":
            raise RuntimeError(f"Refusing unguarded WeChat file send for {chat}: missing send_target")
        run_file_bridge_subprocess(
            [
                sys.executable,
                str(ROOT / "agentic_tools" / "wechat_gui_agent" / "scripts" / "wechat_chatops_bridge.py"),
                "--config",
                os.environ.get(
                    "WECHAT_WORKER_FILE_SEND_CONFIG",
                    str(PRIVATE / "lazy-research-chatops.local.json"),
                ),
                "--chat",
                chat,
                "--file",
                str(file_path.expanduser().resolve()),
            ]
        )
        transport_name = "wechat_gui_unguarded"
    record_event(
        chat_name=chat,
        action="file_send",
        direction="outbound",
        status="sent",
        db_path=DEFAULT_DB,
        metadata={
            "file_identity": file_transport_identity(file_path),
            "transport": transport_name,
        },
    )


def android_file_send_can_fallback_to_desktop(exc: BaseException) -> bool:
    """Allow failover only when Android proved no share action started."""
    if os.environ.get("WECHAT_WORKER_FILE_DESKTOP_PREFLIGHT_FALLBACK", "1") == "0":
        return False
    message = str(exc).upper()
    return any(
        marker in message
        for marker in (
            "ANDROID_WECHAT_TITLE_GUARD",
            "ANDROID_WECHAT_PRECOMMIT_UNAVAILABLE",
            "XDOTOOL SEARCH --NAME ^LABCANVAS\\ ANDROID\\ MIX\\ 2S",
            "ANDROID DEVICE IS NOT AUTHORIZED",
            "NO DEVICES/EMULATORS FOUND",
        )
    )


def reconcile_personal_wechat_delivery_from_mirror(
    task: dict[str, Any],
    *,
    files: list[Path],
    text_fields: dict[str, str],
    db_path: Path = DEFAULT_DB,
) -> dict[str, Any]:
    """Recover exact successful sends lost from an interrupted queue write.

    The mirror is accepted only for the same chat, after this task was created,
    and with an exact file identity or exact visible message part. This keeps a
    crash after native submission from causing duplicate artifacts on replay.
    """
    if task_transport_kind(task) != "wechat":
        return {"files": [], "message_parts": []}
    chat = str(task.get("chat") or "").strip()
    created_at = str(task.get("created_at") or "").strip()
    if not chat or not created_at or not db_path.exists():
        return {"files": [], "message_parts": []}

    try:
        with sqlite3.connect(db_path) as conn:
            rows = conn.execute(
                """
                SELECT e.action, e.direction, e.status, e.message, e.metadata_json
                FROM events AS e
                JOIN chats AS c ON c.id = e.chat_id
                WHERE c.name = ? AND e.created_at >= ?
                  AND e.direction = 'outbound' AND e.status = 'sent'
                ORDER BY e.id
                """,
                (chat, created_at),
            ).fetchall()
    except sqlite3.Error:
        return {"files": [], "message_parts": []}

    sent_identities: list[dict[str, Any]] = []
    sent_messages: set[str] = set()
    for action, _direction, _status, body, metadata_json in rows:
        if action in {"file_send", "send_file"}:
            try:
                metadata = json.loads(metadata_json or "{}")
            except json.JSONDecodeError:
                metadata = {}
            identity = metadata.get("file_identity")
            if isinstance(identity, dict):
                sent_identities.append(identity)
        elif action == "send" and str(body or "").strip():
            sent_messages.add(str(body))

    recovered_files: list[str] = []
    known_sent = {
        str(Path(str(path)).expanduser().resolve())
        for path in task.get("sent_file_paths") or []
    }
    for path in files:
        resolved = path.expanduser().resolve()
        resolved_text = str(resolved)
        if resolved_text in known_sent or not resolved.is_file():
            continue
        identity = file_transport_identity(resolved)
        if not any(exact_file_delivery_identity_matches(identity, sent) for sent in sent_identities):
            continue
        known_sent.add(resolved_text)
        recovered_files.append(resolved_text)
    if recovered_files:
        task["sent_file_paths"] = sorted(known_sent)

    recovered_parts: list[str] = []
    known_hashes = {
        str(value)
        for value in task.get("sent_message_part_hashes") or []
        if str(value)
    }
    for field, value in text_fields.items():
        for part in split_chat_message(value):
            if part not in sent_messages:
                continue
            fingerprint = hashlib.sha256(
                f"{field}\0{part}".encode("utf-8")
            ).hexdigest()
            if fingerprint in known_hashes:
                continue
            known_hashes.add(fingerprint)
            recovered_parts.append(fingerprint)
    if recovered_parts:
        task["sent_message_part_hashes"] = sorted(known_hashes)

    if recovered_files or recovered_parts:
        task.setdefault("delivery_recovery_history", []).append(
            {
                "at": datetime.now().isoformat(timespec="seconds"),
                "source": "exact_personal_wechat_mirror",
                "files": recovered_files,
                "message_part_count": len(recovered_parts),
            }
        )
    return {"files": recovered_files, "message_parts": recovered_parts}


def exact_file_delivery_identity_matches(
    current: dict[str, Any], sent: dict[str, Any]
) -> bool:
    """Match an outbound file without trusting a path or modification time."""
    if str(current.get("name") or "") != str(sent.get("name") or ""):
        return False
    if int(current.get("size_bytes") or -1) != int(sent.get("size_bytes") or -2):
        return False
    current_sha = str(current.get("sha256") or "")
    sent_sha = str(sent.get("sha256") or "")
    if current_sha and sent_sha:
        return current_sha == sent_sha
    current_md5 = str(current.get("md5") or "")
    sent_md5 = str(sent.get("md5") or "")
    return bool(current_md5 and sent_md5 and current_md5 == sent_md5)


def run_desktop_wechat_file_sender(file_path: Path, target: dict[str, Any]) -> None:
    """Send one file through the serialized, exact-title desktop transaction."""
    command = [
        sys.executable,
        str(ROOT / "agentic_tools" / "wechat_gui_agent" / "scripts" / "wechat_gui_send.py"),
        "--targets-file",
        "",
        "--prefer-current",
        "--send",
        "--file",
        str(file_path.expanduser().resolve()),
        "--pause",
        os.environ.get("WECHAT_WORKER_SEND_PAUSE", "0.35"),
        "--mirror-db",
        str(DEFAULT_DB),
    ]
    with tempfile.NamedTemporaryFile(
        "w+", suffix=".json", encoding="utf-8", delete=False
    ) as handle:
        target_file = Path(handle.name)
        json.dump({"message": "", "targets": [target]}, handle, ensure_ascii=False)
    command[command.index("--targets-file") + 1] = str(target_file)
    if gui_search_allowed_for_target(target):
        command.append("--allow-search")
    else:
        command.append("--no-search")
    try:
        run_exact_chat_file_sender(command)
    finally:
        target_file.unlink(missing_ok=True)


def run_android_wechat_sender(
    *,
    chat: str,
    target: dict[str, Any],
    task_id: str,
    messages: list[str] | None = None,
    files: list[Path] | None = None,
) -> dict[str, Any]:
    """Deliver exact-task components through native Android WeChat sharing."""
    target_name = str(target.get("name") or chat).strip() or chat
    command = [
        sys.executable,
        str(WECHAT_ANDROID_SEND_SCRIPT),
        "--targets-file",
        "",
        "--target",
        target_name,
        "--task-id",
        task_id,
        "--send",
    ]
    serial = configured_wechat_unlock_serial()
    if serial:
        command.extend(["--serial", serial])
    for message in messages or []:
        visible = sanitize_chat_visible_text(message, files or [])
        if visible.strip():
            command.extend(["--message", visible])
    for path in files or []:
        command.extend(["--file", str(path.expanduser().resolve())])
    with tempfile.NamedTemporaryFile("w+", suffix=".json", encoding="utf-8", delete=False) as handle:
        target_file = Path(handle.name)
        json.dump({target_name: target}, handle, ensure_ascii=False)
    command[command.index("--targets-file") + 1] = str(target_file)
    timeout = int(os.environ.get("WECHAT_WORKER_ANDROID_SEND_TIMEOUT_SECONDS", "300"))
    try:
        proc = run_subprocess_group(command, timeout=timeout, env=wechat_send_env())
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            f"WECHAT_ANDROID_SEND_TIMEOUT: native sender timed out after {exc.timeout} seconds"
        ) from exc
    finally:
        target_file.unlink(missing_ok=True)
    if proc.returncode != 0:
        detail = compact_exception_text((proc.stderr or proc.stdout or "").strip(), 1200)
        raise RuntimeError(
            f"WECHAT_ANDROID_SEND_FAILED: native sender exited {proc.returncode}: {detail}"
        )
    try:
        payload = json.loads(proc.stdout)
    except json.JSONDecodeError as exc:
        raise RuntimeError("WECHAT_ANDROID_SEND_FAILED: sender returned invalid JSON") from exc
    if not isinstance(payload, dict) or not payload.get("ok"):
        raise RuntimeError("WECHAT_ANDROID_SEND_FAILED: sender did not verify delivery")
    return payload


def run_subprocess_group(command: list[str], *, timeout: int, env: dict[str, str]) -> subprocess.CompletedProcess[str]:
    proc = subprocess.Popen(
        command,
        cwd=ROOT,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        env=env,
        start_new_session=True,
    )
    try:
        stdout, stderr = proc.communicate(timeout=timeout)
    except subprocess.TimeoutExpired as exc:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        stdout, stderr = proc.communicate()
        raise subprocess.TimeoutExpired(command, exc.timeout, output=stdout, stderr=stderr) from exc
    return subprocess.CompletedProcess(command, proc.returncode, stdout, stderr)


def run_send_subprocess(command: list[str], timeout: int | None = None) -> None:
    if timeout is None:
        timeout = int(os.environ.get("WECHAT_WORKER_SEND_TIMEOUT_SECONDS", "120"))
    try:
        proc = run_subprocess_group(command, timeout=timeout, env=wechat_send_env())
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            f"WECHAT_SEND_TIMEOUT: GUI sender timed out after {exc.timeout} seconds; defer this worker reply."
        ) from exc
    if proc.returncode == 0:
        return
    stdout = (proc.stdout or "").strip()
    stderr = (proc.stderr or "").strip()
    parts = [f"send command failed with exit {proc.returncode}"]
    if stdout:
        parts.append(f"stdout={stdout[-1200:]}")
    if stderr:
        parts.append(f"stderr={stderr[-1200:]}")
    raise RuntimeError("; ".join(parts))


def compact_exception_text(exc: BaseException, limit: int = 1200) -> str:
    """Keep both the failure category and the final actionable traceback line."""
    text = str(exc).strip()
    if len(text) <= limit:
        return text
    head = max(160, limit // 4)
    tail = limit - head - 5
    return f"{text[:head]} ... {text[-tail:]}"


def run_file_bridge_subprocess(command: list[str], timeout: int | None = None) -> None:
    if timeout is None:
        timeout = int(
            os.environ.get(
                "WECHAT_WORKER_FILE_SEND_TIMEOUT_SECONDS",
                os.environ.get("WECHAT_WORKER_SEND_TIMEOUT_SECONDS", "120"),
            )
        )
    attempts = max(1, int(os.environ.get("WECHAT_WORKER_FILE_SEND_UNLOCK_RETRIES", "2")) + 1)
    errors: list[str] = []
    for attempt in range(1, attempts + 1):
        proc = run_file_bridge_attempt(command, timeout=timeout)
        if proc.returncode == 0:
            return
        message = file_bridge_failure_message(proc)
        errors.append(f"attempt {attempt}: {message}")
        if attempt < attempts and file_bridge_indicates_wechat_locked(proc) and os.environ.get("WECHAT_WORKER_FILE_SEND_AUTO_UNLOCK", "1") != "0":
            unlock_error = unlock_wechat_for_file_send()
            if unlock_error:
                errors.append(f"unlock attempt {attempt}: {unlock_error}")
            time.sleep(float(os.environ.get("WECHAT_WORKER_FILE_SEND_UNLOCK_RETRY_DELAY", "1.0")))
            continue
        break
    raise RuntimeError("; ".join(errors[-4:]))


def run_exact_chat_file_sender(command: list[str], timeout: int | None = None) -> None:
    """Run exact-target open and native file send in one serialized process."""
    if timeout is None:
        timeout = int(
            os.environ.get(
                "WECHAT_WORKER_FILE_SEND_TIMEOUT_SECONDS",
                os.environ.get("WECHAT_WORKER_SEND_TIMEOUT_SECONDS", "120"),
            )
        )
    attempts = max(1, int(os.environ.get("WECHAT_WORKER_FILE_SEND_UNLOCK_RETRIES", "2")) + 1)
    errors: list[str] = []
    for attempt in range(1, attempts + 1):
        try:
            run_send_subprocess(command, timeout=timeout)
            return
        except RuntimeError as exc:
            message = str(exc)
            errors.append(f"attempt {attempt}: {message}")
            locked = (
                "wechat_locked" in message.lower()
                or "weixin for linux is locked" in message.lower()
                or "状态栏解锁" in message
            )
            if (
                attempt < attempts
                and locked
                and os.environ.get("WECHAT_WORKER_FILE_SEND_AUTO_UNLOCK", "1") != "0"
            ):
                unlock_error = unlock_wechat_for_file_send()
                if unlock_error:
                    errors.append(f"unlock attempt {attempt}: {unlock_error}")
                time.sleep(
                    float(
                        os.environ.get(
                            "WECHAT_WORKER_FILE_SEND_UNLOCK_RETRY_DELAY",
                            "1.0",
                        )
                    )
                )
                continue
            break
    raise RuntimeError("; ".join(errors[-4:]))


def run_file_bridge_attempt(command: list[str], *, timeout: int) -> subprocess.CompletedProcess[str]:
    lock = acquire_gui_send_lock_or_raise()
    try:
        try:
            return run_subprocess_group(command, timeout=timeout, env=wechat_send_env())
        except subprocess.TimeoutExpired as exc:
            raise RuntimeError(
                f"WECHAT_SEND_TIMEOUT: file bridge timed out after {exc.timeout} seconds; defer this worker reply."
            ) from exc
    finally:
        release_gui_send_lock(lock)


def file_bridge_failure_message(proc: subprocess.CompletedProcess[str]) -> str:
    stdout = (proc.stdout or "").strip()
    stderr = (proc.stderr or "").strip()
    parts = [f"file bridge failed with exit {proc.returncode}"]
    if stdout:
        parts.append(f"stdout={stdout[-1200:]}")
    if stderr:
        parts.append(f"stderr={stderr[-1200:]}")
    return "; ".join(parts)


def file_bridge_indicates_wechat_locked(proc: subprocess.CompletedProcess[str]) -> bool:
    text = f"{proc.stdout or ''}\n{proc.stderr or ''}".lower()
    return "wechat_locked" in text or "weixin for linux is locked" in text or "状态栏解锁" in text


def unlock_wechat_for_file_send() -> str:
    env = os.environ.copy()
    env["PYTHONPATH"] = f"{ROOT / 'src'}:{env.get('PYTHONPATH', '')}"
    timeout = int(os.environ.get("WECHAT_WORKER_FILE_SEND_UNLOCK_TIMEOUT_SECONDS", "60"))
    command = [
        sys.executable,
        "-m",
        "agenticapp",
        "wechat",
        "unlock-watchdog",
        "once",
        "--flush-deferred",
        "--json",
    ]
    serial = configured_wechat_unlock_serial()
    if serial:
        command.extend(["--serial", serial])
    try:
        proc = subprocess.run(command, cwd=ROOT, env=env, capture_output=True, text=True, timeout=timeout, check=False)
    except subprocess.TimeoutExpired as exc:
        return f"unlock watchdog timed out after {exc.timeout}s"
    if proc.returncode == 0:
        return ""
    detail = (proc.stderr or proc.stdout or "").strip()
    return detail[-1200:] or f"unlock watchdog failed with exit {proc.returncode}"


def configured_wechat_unlock_serial() -> str:
    direct = (
        os.environ.get("WECHAT_UNLOCK_ADB_SERIAL")
        or os.environ.get("ANDROID_SERIAL")
        or ""
    ).strip()
    if direct:
        return direct
    private_env = PRIVATE / "wechat_supervisor.local.env"
    try:
        lines = private_env.read_text(encoding="utf-8").splitlines()
    except OSError:
        return ""
    for line in lines:
        match = re.match(
            r"^\s*(?:export\s+)?WECHAT_UNLOCK_ADB_SERIAL\s*=\s*(.+?)\s*$",
            line,
        )
        if not match:
            continue
        try:
            values = shlex.split(match.group(1), comments=True)
        except ValueError:
            return ""
        return values[0].strip() if values else ""
    return ""


def gui_send_lock_busy(lock_path: Path = GUI_SEND_LOCK) -> bool:
    reap_stale_orphaned_gui_senders()
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a", encoding="utf-8") as lock:
        acquired = False
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            acquired = True
        except BlockingIOError:
            return True
        finally:
            if acquired:
                try:
                    fcntl.flock(lock, fcntl.LOCK_UN)
                except OSError:
                    pass
    return False


def acquire_gui_send_lock_or_raise(lock_path: Path = GUI_SEND_LOCK):
    reap_stale_orphaned_gui_senders()
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    lock = lock_path.open("a", encoding="utf-8")
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError as exc:
        lock.close()
        raise RuntimeError("WECHAT_SEND_BUSY: serialized GUI sender is already sending; defer this worker reply.") from exc
    return lock


def release_gui_send_lock(lock) -> None:
    try:
        fcntl.flock(lock, fcntl.LOCK_UN)
    finally:
        lock.close()


def reap_stale_orphaned_gui_senders() -> None:
    """Kill orphaned GUI send helpers that can hold the fcntl send lane forever."""
    if os.environ.get("WECHAT_WORKER_DISABLE_STALE_SEND_REAPER") == "1":
        return
    max_age = int(os.environ.get("WECHAT_WORKER_STALE_GUI_SEND_SECONDS", "180"))
    orphan_max_age = int(os.environ.get("WECHAT_WORKER_ORPHAN_GUI_SEND_SECONDS", "15"))
    if max_age <= 0 and orphan_max_age <= 0:
        return
    try:
        proc = subprocess.run(
            ["pgrep", "-f", "agentic_tools/wechat_gui_agent/scripts/wechat_gui_send.py"],
            capture_output=True,
            text=True,
            check=False,
            timeout=2,
        )
    except (OSError, subprocess.SubprocessError):
        return
    for raw_pid in proc.stdout.split():
        try:
            pid = int(raw_pid)
        except ValueError:
            continue
        if pid <= 0 or pid == os.getpid():
            continue
        try:
            stat_proc = subprocess.run(
                ["ps", "-o", "ppid=,etimes=", "-p", str(pid)],
                capture_output=True,
                text=True,
                check=False,
                timeout=2,
            )
        except (OSError, subprocess.SubprocessError):
            continue
        parts = stat_proc.stdout.split()
        if len(parts) < 2:
            continue
        try:
            ppid = int(parts[0])
            age = int(parts[1])
        except ValueError:
            continue
        age_limit = orphan_max_age if ppid == 1 else max_age
        if age_limit <= 0 or age < age_limit:
            continue
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            continue
        except OSError:
            continue


def wechat_send_env() -> dict[str, str]:
    env = os.environ.copy()
    env.setdefault("WECHAT_INITIAL_TITLE_WAIT", os.environ.get("WECHAT_WORKER_INITIAL_TITLE_WAIT", "0.8"))
    env.setdefault("WECHAT_TITLE_RETRY_SECONDS", os.environ.get("WECHAT_WORKER_TITLE_RETRY_SECONDS", "8.0"))
    worker_timeout = int(os.environ.get("WECHAT_WORKER_SEND_TIMEOUT_SECONDS", "120"))
    gui_timeout = os.environ.get("WECHAT_WORKER_GUI_SEND_MAX_SECONDS", str(max(45, worker_timeout - 5)))
    env.setdefault("WECHAT_GUI_SEND_MAX_SECONDS", gui_timeout)
    return env


def guarded_send_target(chat: str, path: Path, *, task: dict[str, Any] | None = None) -> dict[str, Any] | None:
    target = load_send_target(chat, path)
    if target is None:
        if os.environ.get("WECHAT_ALLOW_UNGUARDED_SEND", "0") == "1":
            return None
        raise RuntimeError(f"Refusing unguarded WeChat send for {chat}: missing send_target")
    validate_worker_send_route(task or {"chat": chat}, chat, target)
    return target


def validate_worker_send_route(task: dict[str, Any], target_chat: str, target: dict[str, Any]) -> None:
    route = task.get("route") if isinstance(task.get("route"), dict) else {}
    source = task.get("source") if isinstance(task.get("source"), dict) else {}
    errors: list[str] = []
    task_chat = str(task.get("chat") or "").strip()
    source_chat = str(source.get("chat") or "").strip()
    route_chat = str(route.get("chat") or "").strip()
    target_name = str(target.get("name") or target.get("target") or target.get("query") or "").strip()
    expected_title = str(target.get("expected_title") or target.get("title") or "").strip()
    route_target_name = str(route.get("send_target_name") or "").strip()
    route_expected_title = str(route.get("expected_title") or "").strip()
    if task_chat and task_chat != target_chat:
        errors.append(f"task.chat={task_chat!r} target_chat={target_chat!r}")
    if source_chat and source_chat != target_chat:
        errors.append(f"source.chat={source_chat!r} target_chat={target_chat!r}")
    if route_chat and route_chat != target_chat:
        errors.append(f"route.chat={route_chat!r} target_chat={target_chat!r}")
    if target_name and target_name != target_chat:
        errors.append(f"target.name={target_name!r} target_chat={target_chat!r}")
    if route_target_name and target_name and route_target_name != target_name:
        errors.append(f"route.target={route_target_name!r} resolved.target={target_name!r}")
    if route_expected_title and expected_title and route_expected_title != expected_title:
        errors.append(f"route.expected_title={route_expected_title!r} resolved.expected_title={expected_title!r}")
    if not expected_title and not target.get("expected_title_aliases"):
        errors.append("resolved target has no expected_title/aliases")
    if errors:
        raise RuntimeError("Refusing WeChat send route mismatch: " + "; ".join(errors))


def load_send_target(chat: str, path: Path) -> dict[str, Any] | None:
    direct_target = load_direct_config_send_target(chat)
    registry_target = None
    if not path.exists():
        return direct_target
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return direct_target
    raw = data.get(chat) if isinstance(data, dict) else None
    if isinstance(raw, dict):
        registry_target = raw
    if direct_target and registry_target:
        return {**direct_target, **registry_target}
    return direct_target or registry_target


def load_direct_config_send_target(chat: str) -> dict[str, Any] | None:
    for config_path in PRIVATE.glob("*direct-chatops.local.json"):
        try:
            data = json.loads(config_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if str(data.get("chat_name") or "") != chat:
            continue
        target = data.get("send_target")
        if isinstance(target, dict):
            return target
    return None


if __name__ == "__main__":
    raise SystemExit(main())
